{"cards": [{"node_code": "N_c1abc4ebb5c296a3", "definition": "研究塑料成形后的修整、表面处理、装配等后处理工艺，热成型（如吸塑、吹塑）的具体技术，以及注射、挤出等核心工艺的参数设定与优化方法。", "boundary": "聚焦于成形过程的参数控制（温度、压力、时间）及成形后的物理/化学状态调整。边界在于关注“工艺执行”与“参数逻辑”，区别于模具的机械结构设计（归入“注塑模具结构”）和成形结果的缺陷分析（归入“塑料成形缺陷”）。", "includes": ["注射、挤出、吹塑等工艺的温度、压力、速度参数优化", "热成型（吸塑、真空成型）工艺及模具配合技术", "塑件去毛刺、喷涂、电镀、焊接等后处理工艺"], "excludes": ["注塑模具的型腔、流道、冷却水路等机械结构设计", "塑件内部应力、翘曲、缩孔等缺陷机理分析与质量判定"], "sibling_distinctions": [{"other_code": "N_8e83b86a34a9c917", "rule": "本节点关注工艺参数设定与后处理流程，兄弟节点关注模具的机械结构、流道系统及运动机构设计。"}, {"other_code": "N_5c50fa86c9eb6b1d", "rule": "本节点关注如何设定参数以达成目标及后续处理，兄弟节点关注成形后出现的质量问题、缺陷机理及试模验证过程。"}], "cross_boundary_rule": "若研究重点在于通过调整工艺参数解决特定缺陷，主挂载本节点；若重点在于缺陷本身的物理机理或检测标准，主挂载“塑料成形缺陷”。"}, {"node_code": "N_5c50fa86c9eb6b1d", "definition": "研究塑料成形过程中产生的各类缺陷（如缩孔、飞边、翘曲）的成因、检测、预防及制品质量评估标准，以及通过试模验证工艺与模具可行性的方法。", "boundary": "聚焦于“结果导向”的质量控制，包括缺陷机理分析、质量指标（尺寸、外观、力学性能）及试模流程。边界在于关注成形结果的符合性与问题诊断，区别于工艺参数的常规设定（归入“塑件后处理、热成型与工艺参数”）和模具结构设计（归入“注塑模具结构”）。", "includes": ["缩孔、银纹、熔接痕、翘曲等常见缺陷的机理分析与对策", "试模流程、工艺窗口验证及模具调试方法", "塑件尺寸精度、外观质量及力学性能检测与评估"], "excludes": ["注塑模具的机械结构、浇口位置及抽芯机构设计", "常规工艺参数（温度、压力）的理论计算与优化模型"], "sibling_distinctions": [{"other_code": "N_c1abc4ebb5c296a3", "rule": "本节点关注成形结果的缺陷分析与质量验证，兄弟节点关注工艺参数的设定逻辑及成形后的后处理工艺。"}, {"other_code": "N_8e83b86a34a9c917", "rule": "本节点关注模具与工艺配合产生的质量结果，兄弟节点关注模具本身的机械结构设计与运动原理。"}], "cross_boundary_rule": "若研究旨在通过试模发现并解决具体缺陷，主挂载本节点；若研究旨在建立通用的缺陷预测模型或材料流变理论，可结合材料学科，但在制造语境下通常归入本节点。"}, {"node_code": "N_8e83b86a34a9c917", "definition": "研究注塑模具的机械结构组成，包括型腔、型芯、浇注系统（浇口、流道）、冷却系统、顶出系统及抽芯、侧向分型等复杂运动机构的设计与优化。", "boundary": "聚焦于模具作为“工装装备”的机械设计与工程实现。边界在于关注模具的物理结构、运动逻辑及热管理设计，区别于塑料材料的加工流变特性（归入“塑件后处理、热成型与工艺参数”）和成形后的质量缺陷分析（归入“塑料成形缺陷”）。", "includes": ["注塑模具的型腔、型芯、分型面及浇注系统设计", "抽芯、侧向分型、滑块、斜顶等复杂机构设计", "模具冷却水路、顶出系统及模具材料选择与寿命分析"], "excludes": ["塑料注射成形的温度、压力、时间等工艺参数设定", "塑件成形后的缺陷机理分析、试模验证及后处理工艺"], "sibling_distinctions": [{"other_code": "N_c1abc4ebb5c296a3", "rule": "本节点关注模具的机械结构与运动机构设计，兄弟节点关注成形工艺参数设定及后处理流程。"}, {"other_code": "N_5c50fa86c9eb6b1d", "rule": "本节点关注模具硬件本身的设计，兄弟节点关注模具与工艺配合后的质量结果、缺陷分析及试模过程。"}], "cross_boundary_rule": "若研究涉及模具结构对流动的影响（如流道设计），主挂载本节点；若研究涉及模具结构导致的特定缺陷（如顶白），需结合“塑料成形缺陷”节点，但模具设计主体归本节点。"}]}
